11	/*!
12	 * \file muls.cpp
13	 * \brief 通过muls算子示例，展示用户不同输入信息，不同Compute表达的运算过程，并展示表达式中使用scalar的方式
14	 */
15	
16	#include "kernel_operator.h"
17	#include "atvoss.h"
18	#include "example_common.h"
19	#include "command_line.h"
20	
21	static constexpr int32_t WIDTH = 32;
22	static constexpr int32_t MAX_DIM = 8;
23	
24	template <typename TensorDtype, typename ScalarDtype>
25	struct MulsConfig {
26	    using TileShape = Atvoss::Shape<WIDTH>;
27	
28	    struct MulsCompute {
29	        template <template <typename> class Tensor>
30	        __host_aicore__ constexpr auto Compute() const
31	        {
32	            auto in = Atvoss::PlaceHolder<1, Tensor<TensorDtype>, Atvoss::ParamUsage::IN>();
33	            auto scalar = Atvoss::PlaceHolder<2, ScalarDtype, Atvoss::ParamUsage::IN>();
34	            auto out = Atvoss::PlaceHolder<3, Tensor<TensorDtype>, Atvoss::ParamUsage::OUT>();
35	
36	            return (out = in * scalar);
37	        };
38	    };
39	
40	    struct MulsComputePromtIn {
41	        template <template <typename> class Tensor>
42	        __host_aicore__ constexpr auto Compute() const
43	        {
44	            auto in = Atvoss::PlaceHolder<1, Tensor<TensorDtype>, Atvoss::ParamUsage::IN>();
45	            auto scalar = Atvoss::PlaceHolder<2, ScalarDtype, Atvoss::ParamUsage::IN>();
46	            auto out = Atvoss::PlaceHolder<3, Tensor<ScalarDtype>, Atvoss::ParamUsage::OUT>();
47	            auto inTmp = Atvoss::PlaceHolderTmpLike<1, Tensor<ScalarDtype>>(in);
48	
49	            return (inTmp = Atvoss::Cast<Atvoss::CastMode::CAST_NONE, ScalarDtype>(in), out = inTmp * scalar);
50	        };
51	    };
52	
53	    static constexpr Atvoss::Ele::DefaultBlockPolicy<TileShape> blockPolicy{TileShape{}};
54	    static constexpr Atvoss::Ele::DefaultKernelPolicy kernelPolicy{Atvoss::Ele::DefaultSegmentPolicy::UniformSegment};
55	    using ArchTag = Atvoss::Arch::DAV_3510;
56	    using BlockOp = Atvoss::Ele::BlockBuilder<
57	        MulsCompute, ArchTag, blockPolicy, Atvoss::Ele::DefaultBlockConfig, Atvoss::Ele::DefaultBlockSchedule>;
58	
59	    using BlockOpPromtIn = Atvoss::Ele::BlockBuilder<
60	        MulsComputePromtIn, ArchTag, blockPolicy, Atvoss::Ele::DefaultBlockConfig, Atvoss::Ele::DefaultBlockSchedule>;
61	
62	    using KernelOp = Atvoss::Ele::KernelBuilder<
63	        BlockOp, kernelPolicy, Atvoss::Ele::DefaultKernelConfig, Atvoss::Ele::DefaultKernelSchedule>;
64	    using KernelOpPromtIn = Atvoss::Ele::KernelBuilder<
65	        BlockOpPromtIn, kernelPolicy, Atvoss::Ele::DefaultKernelConfig, Atvoss::Ele::DefaultKernelSchedule>;
66	
67	    using DeviceOp = Atvoss::DeviceAdapter<KernelOp>;
68	    using DeviceOpPromtIn = Atvoss::DeviceAdapter<KernelOpPromtIn>;
69	};
70	
71	struct Options {
72	    // 存储解析后的值
73	    std::vector<int> shape;
74	    bool help;
75	
76	    // 默认构造：不解析，只设默认值
77	    Options() : shape({}), help(false)
78	    {}
79	
80	    // 解析函数
81	    void parse(int argc, char const* argv[])
82	    {
83	        CommandLine cmd(argc, argv);
84	
85	        help = cmd.Present("help") || cmd.Present("h");
86	        shape = cmd.Get("shape", std::vector<int>{});
87	
88	        validate(argv[0]);
89	    }
90	
91	    // 打印使用说明
92	    void PrintUsage(const char* progName = nullptr) const
93	    {
94	        if (!progName)
95	            progName = "program";
96	
97	        std::cout << "Usage: " << progName << " [options]\n"
98	                  << "\n"
99	                  << "Options:\n"
100	                  << "  --help                      Print this message\n"
101	                  << "  --shape=M,N,O,...           Tensor dimensions (e.g., --shape=4,3,224,224)\n"
102	                  << "\n"
103	                  << "Example:\n"
104	                  << "  " << progName << " --shape=4,3,224,224 \n";
105	    }
106	
107	private:
108	    void validate(const char* progName)
109	    {
110	        if (help) {
111	            return; // 帮助不需要验证
112	        }
113	
114	        if (shape.empty()) {
115	            std::cerr << "[ERROR] Missing required argument: --shape\n";
116	            PrintUsage(progName);
117	            exit(1);
118	        }
119	        if (shape.size() > MAX_DIM) {
120	            std::cerr << "[ERROR] Input shape max dim is 8, current shape dim is: " << shape.size() << "\n";
121	            PrintUsage(progName);
122	            exit(1);
123	        }
124	        for (int d : shape) {
125	            if (d < 0) {
126	                std::cerr << "[ERROR] Invalid dimension size: " << d << "\n";
127	                exit(1);
128	            }
129	        }
130	    }
131	};
132	
133	template <typename TensorDtype, typename ScalarDtype>
134	static void Run(const Options& options)
135	{
136	    // --- Step 1: ACL 初始化 ---
137	    CHECK_ACL_RET(aclInit(nullptr));
138	    auto finalizeGuard = ReleaseSource([]() { aclFinalize(); });
139	
140	    // --- Step 2: 设置 device ID ---
141	    const int32_t deviceId = 0;
142	    CHECK_ACL_RET(aclrtSetDevice(deviceId));
143	    auto deviceResetGuard = ReleaseSource([deviceId]() { aclrtResetDevice(deviceId); });
144	
145	    // --- Step 3: 创建 Context ---
146	    aclrtContext context = nullptr;
147	    CHECK_ACL_RET(aclrtCreateContext(&context, deviceId));
148	    auto contextDestroyGuard = ReleaseSource([context]() { aclrtDestroyContext(context); });
149	
150	    // --- Step 4: 创建 Stream ---
151	    aclrtStream stream = nullptr;
152	    CHECK_ACL_RET(aclrtCreateStream(&stream));
153	    auto streamDestroyGuard = ReleaseSource([stream]() { aclrtDestroyStream(stream); });
154	
155	    // --- Step 5: 分配输入/输出的Device内存 ---
156	    const auto& shape = options.shape;
157	    const size_t shapeSize = std::accumulate(shape.begin(), shape.end(), size_t{1}, std::multiplies<>{});
158	    const size_t inputSize = shapeSize * sizeof(TensorDtype);
159	    const size_t outputSize = shapeSize * sizeof(ScalarDtype);
160	    void* rawInput = nullptr;
161	    CHECK_ACL_RET(aclrtMalloc(&rawInput, inputSize, ACL_MEM_MALLOC_HUGE_FIRST));
162	    auto inputFreeGuard = ReleaseSource([rawInput]() { aclrtFree(rawInput); });
163	    TensorDtype* deviceInput = static_cast<TensorDtype*>(rawInput);
164	    void* rawOutput = nullptr;
165	    CHECK_ACL_RET(aclrtMalloc(&rawOutput, outputSize, ACL_MEM_MALLOC_HUGE_FIRST));
166	    auto outputFreeGuard = ReleaseSource([rawOutput]() { aclrtFree(rawOutput); });
167	    ScalarDtype* deviceOutput = static_cast<ScalarDtype*>(rawOutput);
168	
169	    // --- Step 6: Host -> Device 数据拷贝 ---
170	    std::vector<TensorDtype> hostInput(shapeSize, static_cast<TensorDtype>(3.0f));
171	    CHECK_ACL_RET(aclrtMemcpy(deviceInput, inputSize, hostInput.data(), inputSize, ACL_MEMCPY_HOST_TO_DEVICE));
172	
173	    // --- Step 7: 构造参数信息 ---
174	    uint64_t shapeArray[MAX_DIM] = {0};
175	    std::copy(shape.begin(), shape.end(), shapeArray);
176	    Atvoss::Tensor<TensorDtype> in(deviceInput, shapeArray, shape.size());
177	    Atvoss::Tensor<ScalarDtype> out(deviceOutput, shapeArray, shape.size());
178	    float scalar = 3.0f;
179	    auto arguments = Atvoss::ArgumentsBuilder{}.inputOutput(in, scalar, out).build();
180	
181	    // --- Step 8: 执行算子 ---
182	    if constexpr (std::is_same_v<TensorDtype, float>) {
183	        using DeviceOp = typename MulsConfig<TensorDtype, ScalarDtype>::DeviceOp;
184	        DeviceOp deviceOp;
185	        deviceOp.Run(arguments, stream);
186	    } else if constexpr (std::is_same_v<TensorDtype, int32_t>) {
187	        using DeviceOp = typename MulsConfig<TensorDtype, ScalarDtype>::DeviceOpPromtIn;
188	        DeviceOp deviceOp;
189	        deviceOp.Run(arguments, stream);
190	    }
191	
192	    // --- Step 9: 同步并拷回结果 ---
193	    CHECK_ACL_RET(aclrtSynchronizeStream(stream));
194	    std::vector<ScalarDtype> hostOutput(shapeSize);
195	    CHECK_ACL_RET(aclrtMemcpy(hostOutput.data(), outputSize, deviceOutput, outputSize, ACL_MEMCPY_DEVICE_TO_HOST));
196	
197	    // --- Step 10: 验证结果 ---
198	    std::vector<ScalarDtype> golden(shapeSize, 9.0f);
199	    if (!VerifyResults(golden, hostOutput)) {
200	        std::cout << "Accuracy verification failed." << std::endl;
201	    } else {
202	        std::cout << "Accuracy verification passed." << std::endl;
203	    }
204	}
205	
206	int main(int argc, char const* argv[])
207	{
208	    Options options;
209	    options.parse(argc, argv);
210	
211	    if (options.help) {
212	        options.PrintUsage(argv[0]);
213	        return 0;
214	    }
215	
216	    // 继续执行计算逻辑
217	    std::cout << "Start muls int32_t and float" << std::endl;
218	    Run<int32_t, float>(options);
219	
220	    return 0;
221	}
